  var raw := pairArr;
  var srt := Sort(raw, (x: (int, int), y: (int, int)) => x.0 < y.0 || (x.0 == y.0 && x.1 < y.1));
  steps := steps + SortCost(nn);
  SortCostWithin(nn, m);
  ghost var s1 := steps;

  var BIG := -1000000000000000000;
  var aArr := seq(m, _ => 0);
  var bArr := seq(m, _ => 0);
  aArr := aArr[0 := BIG];
  bArr := bArr[0 := 0];
  steps := steps + 2 * m + 2;
  var j := 0;
