    aArr := aArr[j+1 := srt[j].0];
    bArr := bArr[j+1 := srt[j].1];
    j := j + 1;
    steps := steps + 3;
  }

  var dptable := seq(m, _ => 1);
  dptable := dptable[0 := 0];
  steps := steps + m + 1;
  ghost var base := steps;
  ghost var K: nat := 3 * SearchPot(m) + 6;
  var k := 1;
  while k < m
    invariant 1 <= k <= m
    invariant |aArr| == m && |bArr| == m && |dptable| == m
    invariant steps <= base + (k - 1) * K
