    } else {
      dptable := dptable[k := 1];
    }
    k := k + 1;
    steps := steps + 5;
    CostMulDistrib(k - 2, 1, k - 1, K);
  }
  SearchLoopWithin(m - 1, m, m, 3, 6);
  assert steps <= base + 3 * NLogN(m) + 6 * m;
  ghost var s4 := steps;

  var best := dptable[0];
  var p := 1;
  while p < m
    invariant 1 <= p <= m
    invariant |dptable| == m
    invariant steps == s4 + 2 * (p - 1)
  {
    if dptable[p] > best { best := dptable[p]; }
    p := p + 1;
    steps := steps + 2;
  }
  output := IntToString(n - best);
  steps := steps + 2;
}
